const pipeline = [
  {
    title: "Entrada redactada",
    detail: "El flujo recibe solo campos sinteticos y textos saneados.",
    status: "aislado",
    color: "#2e6f8f"
  },
  {
    title: "Normalizacion",
    detail: "Los identificadores sensibles se reemplazan por tokens publicos.",
    status: "limpio",
    color: "#b56b16"
  },
  {
    title: "Validacion",
    detail: "La evidencia se valida por archivos y render real de navegador.",
    status: "activo",
    color: "#2f7d58"
  },
  {
    title: "Cierre bloqueable",
    detail: "El cierre depende de pruebas y no de memoria implicita.",
    status: "verificado",
    color: "#b6423c"
  }
];

const records = [
  ["frontend/index.html", "pantalla", "presente"],
  ["frontend/styles.css", "estilos", "presente"],
  ["frontend/app.js", "logica", "presente"],
  ["secrets", "datos reales", "no usados"]
];

const state = {
  distance: 128,
  speed: 14,
  frame: 0,
  light: "day"
};

function qs(name) {
  return new URLSearchParams(window.location.search).get(name);
}

function setHud() {
  const mode = qs("mode") || "smoke";
  document.getElementById("distance-value").textContent = `${state.distance} m`;
  document.getElementById("speed-value").textContent = `${state.speed} m/s`;
  document.getElementById("mode-value").textContent = mode;
  document.getElementById("event-value").textContent = "fallback-2d listo";
}

function renderPipeline() {
  const list = document.getElementById("pipeline-list");
  list.innerHTML = "";
  pipeline.forEach((item) => {
    const row = document.createElement("article");
    row.className = "pipeline-item";

    const marker = document.createElement("span");
    marker.className = "pipeline-marker";
    marker.style.background = item.color;

    const copy = document.createElement("div");
    const title = document.createElement("h3");
    const detail = document.createElement("p");
    title.textContent = item.title;
    detail.textContent = item.detail;
    copy.append(title, detail);

    const badge = document.createElement("span");
    badge.className = "pipeline-badge";
    badge.textContent = item.status;

    row.append(marker, copy, badge);
    list.append(row);
  });
}

function renderRecords() {
  const table = document.getElementById("records-table");
  table.innerHTML = "";
  records.forEach(([artifact, type, status]) => {
    const row = document.createElement("tr");
    [artifact, type, status].forEach((value) => {
      const cell = document.createElement("td");
      cell.textContent = value;
      row.append(cell);
    });
    table.append(row);
  });
}

function fitCanvas(canvas) {
  const ratio = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = Math.max(640, Math.floor(rect.width * ratio));
  canvas.height = Math.max(420, Math.floor(rect.height * ratio));
  return ratio;
}

function drawWorld() {
  const canvas = document.getElementById("world");
  canvas.dataset.renderMode = "fallback-2d";
  const ctx = canvas.getContext("2d");
  if (!ctx) {
    document.getElementById("event-value").textContent = "canvas no disponible";
    return;
  }

  const ratio = fitCanvas(canvas);
  const width = canvas.width;
  const height = canvas.height;
  ctx.clearRect(0, 0, width, height);
  ctx.scale(ratio, ratio);

  const logicalWidth = width / ratio;
  const logicalHeight = height / ratio;
  ctx.fillStyle = state.light === "day" ? "#e8ede4" : "#d9e0d5";
  ctx.fillRect(0, 0, logicalWidth, logicalHeight);

  ctx.strokeStyle = "rgba(23, 32, 27, 0.12)";
  ctx.lineWidth = 1;
  for (let x = 40; x < logicalWidth; x += 80) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, logicalHeight);
    ctx.stroke();
  }
  for (let y = 40; y < logicalHeight; y += 80) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(logicalWidth, y);
    ctx.stroke();
  }

  const nodes = pipeline.map((item, index) => ({
    ...item,
    x: 120 + index * ((logicalWidth - 240) / Math.max(1, pipeline.length - 1)),
    y: logicalHeight * 0.42 + Math.sin((state.frame + index * 18) / 24) * 18
  }));

  ctx.lineWidth = 5;
  ctx.strokeStyle = "#2e6f8f";
  ctx.beginPath();
  nodes.forEach((node, index) => {
    if (index === 0) ctx.moveTo(node.x, node.y);
    else ctx.lineTo(node.x, node.y);
  });
  ctx.stroke();

  nodes.forEach((node, index) => {
    ctx.fillStyle = node.color;
    ctx.beginPath();
    ctx.arc(node.x, node.y, 30, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = "#ffffff";
    ctx.font = "700 18px system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(String(index + 1), node.x, node.y);

    ctx.fillStyle = "#17201b";
    ctx.font = "700 14px system-ui, sans-serif";
    ctx.fillText(node.title, node.x, node.y + 52);
  });

  ctx.fillStyle = "rgba(255, 255, 255, 0.86)";
  ctx.fillRect(28, 28, 300, 92);
  ctx.fillStyle = "#17201b";
  ctx.font = "800 20px system-ui, sans-serif";
  ctx.textAlign = "left";
  ctx.fillText("Arquitectura segura", 48, 64);
  ctx.font = "500 14px system-ui, sans-serif";
  ctx.fillStyle = "#667067";
  ctx.fillText("Sin credenciales, sin bypasses, sin datos reales", 48, 92);
}

function tick() {
  state.frame += 1;
  state.distance += 3;
  state.speed = 14 + (state.frame % 5);
  setHud();
  drawWorld();
  window.requestAnimationFrame(tick);
}

function bindControls() {
  document.querySelector("[data-action='rerun']").addEventListener("click", () => {
    state.distance += 17;
    state.speed = 18;
    setHud();
    drawWorld();
  });

  document.querySelector("[data-action='toggle']").addEventListener("click", () => {
    state.light = state.light === "day" ? "night" : "day";
    document.body.classList.toggle("theme-night", state.light === "night");
    drawWorld();
  });

  window.addEventListener("resize", drawWorld);
}

function init() {
  renderPipeline();
  renderRecords();
  setHud();
  bindControls();
  drawWorld();
  window.requestAnimationFrame(tick);
}

document.addEventListener("DOMContentLoaded", init);

:root {
  color-scheme: light;
  --bg: #f6f7f4;
  --panel: #ffffff;
  --ink: #17201b;
  --muted: #667067;
  --line: #d9ded4;
  --green: #2f7d58;
  --amber: #b56b16;
  --red: #b6423c;
  --blue: #2e6f8f;
  --shadow: 0 18px 45px rgba(23, 32, 27, 0.12);
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  color: var(--ink);
  background: var(--bg);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

button,
input,
select {
  font: inherit;
}

.app-shell {
  min-height: 100vh;
  padding: 24px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  max-width: 1400px;
  margin: 0 auto 18px;
}

.eyebrow {
  margin: 0 0 5px;
  color: var(--muted);
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: uppercase;
}

h1,
h2 {
  margin: 0;
  letter-spacing: 0;
}

h1 {
  font-size: clamp(2rem, 3rem, 3rem);
  line-height: 1;
}

h2 {
  font-size: 1.22rem;
  line-height: 1.25;
}

.status-strip {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-height: 40px;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--panel);
  color: var(--muted);
  white-space: nowrap;
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--green);
}

.status-divider {
  width: 1px;
  height: 18px;
  background: var(--line);
}

.workspace {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(360px, 0.85fr);
  gap: 18px;
  max-width: 1400px;
  margin: 0 auto;
}

.visual-panel,
.operations {
  min-width: 0;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--panel);
  box-shadow: var(--shadow);
}

.visual-panel {
  position: relative;
  overflow: hidden;
  min-height: 560px;
}

#world {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 560px;
  background: #e8ede4;
}

.hud {
  position: absolute;
  left: 18px;
  bottom: 18px;
  display: grid;
  grid-template-columns: repeat(3, minmax(112px, 1fr));
  gap: 8px;
  width: min(94%, 520px);
}

.hud > div {
  min-height: 64px;
  padding: 10px 12px;
  border: 1px solid rgba(23, 32, 27, 0.12);
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.9);
}

.metric-label {
  display: block;
  margin-bottom: 5px;
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0;
  text-transform: uppercase;
}

.hud strong {
  display: block;
  overflow-wrap: anywhere;
  font-size: 1.22rem;
}

.operations {
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 20px;
}

.section-heading {
  display: grid;
  gap: 4px;
}

.control-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.primary-action,
.secondary-action {
  min-height: 42px;
  border: 1px solid transparent;
  border-radius: 6px;
  cursor: pointer;
}

.primary-action {
  color: #ffffff;
  background: var(--green);
}

.secondary-action {
  color: var(--ink);
  background: #f4efe6;
  border-color: #dcc9a9;
}

.primary-action:focus-visible,
.secondary-action:focus-visible {
  outline: 3px solid rgba(46, 111, 143, 0.35);
  outline-offset: 2px;
}

.pipeline-list {
  display: grid;
  gap: 10px;
}

.pipeline-item {
  display: grid;
  grid-template-columns: 14px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  min-height: 64px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #fbfcf8;
}

.pipeline-marker {
  width: 14px;
  height: 14px;
  border-radius: 50%;
}

.pipeline-item h3 {
  margin: 0 0 4px;
  font-size: 0.98rem;
  letter-spacing: 0;
}

.pipeline-item p {
  margin: 0;
  color: var(--muted);
  font-size: 0.88rem;
  line-height: 1.35;
}

.pipeline-badge {
  min-width: 76px;
  padding: 5px 8px;
  border-radius: 6px;
  background: #eef3ed;
  color: var(--green);
  font-size: 0.78rem;
  font-weight: 800;
  text-align: center;
}

.evidence-table-wrap {
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.evidence-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 420px;
}

.evidence-table caption {
  padding: 12px;
  color: var(--muted);
  font-weight: 700;
  text-align: left;
}

.evidence-table th,
.evidence-table td {
  padding: 11px 12px;
  border-top: 1px solid var(--line);
  text-align: left;
  vertical-align: top;
}

.evidence-table th {
  background: #f4f6ef;
  color: var(--muted);
  font-size: 0.78rem;
  letter-spacing: 0;
  text-transform: uppercase;
}

.evidence-table td {
  font-size: 0.9rem;
}

.theme-night {
  --bg: #101611;
  --panel: #f7f8f2;
  --ink: #152018;
  --muted: #5f6a62;
}

@media (max-width: 980px) {
  .app-shell {
    padding: 16px;
  }

  .topbar {
    align-items: flex-start;
    flex-direction: column;
  }

  .status-strip {
    width: 100%;
    flex-wrap: wrap;
    white-space: normal;
  }

  .workspace {
    grid-template-columns: 1fr;
  }

  .visual-panel,
  #world {
    min-height: 460px;
  }
}

@media (max-width: 620px) {
  .hud {
    grid-template-columns: 1fr;
    width: calc(100% - 24px);
    left: 12px;
    bottom: 12px;
  }

  .control-row {
    grid-template-columns: 1fr;
  }

  h1 {
    font-size: 2rem;
  }
}

from __future__ import annotations

from dataclasses import asdict, dataclass, field
from datetime import UTC, datetime
from typing import Any, Mapping


ALLOWED_MODES = ("smoke", "build", "medium", "long-run")
TASK_STATUSES = ("pending", "running", "completed", "failed", "blocked")


class ContractError(ValueError):
    """Raised when persisted runtime data does not match the contract."""


def utc_now_iso() -> str:
    return datetime.now(UTC).isoformat()


def _string_list(value: Any, field_name: str) -> list[str]:
    if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
        raise ContractError(f"{field_name} must be a list of strings")
    return list(value)


@dataclass(frozen=True)
class Task:
    id: str
    title: str
    goal: str
    status: str
    priority: int
    dependencies: list[str] = field(default_factory=list)
    expected_files: list[str] = field(default_factory=list)
    validation_commands: list[str] = field(default_factory=list)
    timeout_seconds: int = 900
    max_retries: int = 3
    mode: str = "build"
    checkpoint_key: str | None = None

    @classmethod
    def from_mapping(cls, payload: Mapping[str, Any]) -> "Task":
        task = cls(
            id=str(payload.get("id") or ""),
            title=str(payload.get("title") or ""),
            goal=str(payload.get("goal") or ""),
            status=str(payload.get("status") or ""),
            priority=int(payload.get("priority", 0)),
            dependencies=_string_list(payload.get("dependencies", []), "dependencies"),
            expected_files=_string_list(payload.get("expected_files", []), "expected_files"),
            validation_commands=_string_list(payload.get("validation_commands", []), "validation_commands"),
            timeout_seconds=int(payload.get("timeout_seconds", 0)),
            max_retries=int(payload.get("max_retries", 0)),
            mode=str(payload.get("mode") or ""),
            checkpoint_key=payload.get("checkpoint_key"),
        )
        task.validate()
        return task

    def validate(self) -> None:
        if not self.id or not self.title or not self.goal:
            raise ContractError("task id, title and goal are required")
        if self.status not in TASK_STATUSES:
            raise ContractError(f"invalid task status: {self.status}")
        if self.mode not in ALLOWED_MODES:
            raise ContractError(f"invalid task mode: {self.mode}")
        if self.timeout_seconds <= 0:
            raise ContractError("timeout_seconds must be greater than zero")
        if self.max_retries < 0:
            raise ContractError("max_retries cannot be negative")
        if self.checkpoint_key is not None and not isinstance(self.checkpoint_key, str):
            raise ContractError("checkpoint_key must be a string or null")

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass(frozen=True)
class TaskResult:
    task_id: str
    completed: bool
    files_created: list[str] = field(default_factory=list)
    files_modified: list[str] = field(default_factory=list)
    validation_ran: list[str] = field(default_factory=list)
    validation_passed: bool = False
    blockers: list[str] = field(default_factory=list)
    next_recommendation: str = ""

    def validate(self) -> None:
        if not self.task_id:
            raise ContractError("task_result.task_id is required")
        if self.completed and (not self.validation_passed or self.blockers):
            raise ContractError("completed task results require passed validation and no blockers")

    def to_dict(self) -> dict[str, Any]:
        self.validate()
        return asdict(self)


@dataclass(frozen=True)
class ProjectState:
    project_slug: str
    status: str
    mode: str
    updated_at: str = field(default_factory=utc_now_iso)

    @classmethod
    def from_mapping(cls, payload: Mapping[str, Any]) -> "ProjectState":
        state = cls(
            project_slug=str(payload.get("project_slug") or payload.get("projectSlug") or ""),
            status=str(payload.get("status") or ""),
            mode=str(payload.get("mode") or ""),
            updated_at=str(payload.get("updated_at") or payload.get("updatedAt") or utc_now_iso()),
        )
        state.validate()
        return state

    def validate(self) -> None:
        if not self.project_slug:
            raise ContractError("project_slug is required")
        if self.mode not in ALLOWED_MODES:
            raise ContractError(f"invalid project mode: {self.mode}")
        if not self.status:
            raise ContractError("project status is required")

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)
